const output = $input.first().json.output
  || $input.first().json.text
  || $input.first().json.message
  || '';

// Safety check FIRST
if (output.includes('search_metadata') || output.includes('HTTP_Request')) {
  return [{ json: { cleanText: 'Sorry, could not format results. Please try again.' } }];
}

// Then clean and return
const clean = output
  .replace(/\*\*/g, '')
  .replace(/\*/g, '')
  .replace(/###/g, '')
  .replace(/##/g, '')
  .replace(/#/g, '')
  .replace(/`/g, '');

const truncated = clean.length > 4000
  ? clean.substring(0, 4000) + '\n[Truncated]'
  : clean;
const formatted = truncated.replace(/\b(\d{5,})\b/g, (match) => {
  return parseInt(match).toLocaleString('en-IN');
});
return [{ json: { cleanText: formatted } }];
